import{_ as d,o as a,c as r,a2 as h}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"Ключевые Личности и Организации","description":"","frontmatter":{},"headers":[],"relativePath":"ru/95-关键人物与组织.md","filePath":"ru/95-关键人物与组织.md","lastUpdated":null}'),e={name:"ru/95-关键人物与组织.md"};function i(n,t,o,l,b,s){return a(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="ключевые-личности-и-организации" tabindex="-1">Ключевые Личности и Организации <a class="header-anchor" href="#ключевые-личности-и-организации" aria-label="Permalink to &quot;Ключевые Личности и Организации&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>Номер документа</td><td>95</td></tr><tr><td>Модуль</td><td>Приложения и справочные материалы</td></tr><tr><td>Ключевые слова</td><td>ключевые личности, важные организации, исторические роли, функции институтов, симбиотическая цивилизация</td></tr></tbody></table><h2 id="i-пояснения" tabindex="-1">I. Пояснения <a class="header-anchor" href="#i-пояснения" aria-label="Permalink to &quot;I. Пояснения&quot;">​</a></h2><p>Настоящий документ охватывает ключевых личностей и важные организации в истории развития Симбиотической Цивилизации Якоря, сгруппированные по историческим периодам и типам организаций. В разделе ключевых личностей для каждой личности указаны имя, период, ключевой вклад и историческое положение; в разделе важных организаций для каждой организации указаны название, время основания, ключевые функции и историческая роль. Настоящий документ является динамически обновляемым: по мере продвижения истории и эволюции организаций он будет постоянно дополняться и пересматриваться.</p><h2 id="ii-ключевые-личности" tabindex="-1">II. Ключевые Личности <a class="header-anchor" href="#ii-ключевые-личности" aria-label="Permalink to &quot;II. Ключевые Личности&quot;">​</a></h2><h3 id="_2-1-мыслители-предтечи-до-якорнои-эпохи" tabindex="-1">2.1 Мыслители-предтечи до-якорной эпохи <a class="header-anchor" href="#_2-1-мыслители-предтечи-до-якорнои-эпохи" aria-label="Permalink to &quot;2.1 Мыслители-предтечи до-якорной эпохи&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Имя</th><th>Период</th><th>Ключевой вклад</th><th>Историческое положение</th></tr></thead><tbody><tr><td>Xuánhéng Zǐ</td><td>ок. −500 млн лет</td><td>Первый мыслитель, систематически осмысливший хищническую систему культивации; предложил прообраз концепции «симбиоза»; автор сохранившегося фрагмента Fǎn Lüèduó Lùn (Трактат против Хищничества)</td><td>Древний предтеча симбиотической мысли; его мысль, проспав сотни миллионов лет, стала духовным истоком Симбиотической Цивилизации Якоря</td></tr><tr><td>Wànlíng Mǔ</td><td>ок. −100 млн лет</td><td>Возглавила первую масштабную экспериментальную симбиотическую цивилизацию; хотя в итоге была уничтожена хищническими цивилизациями, её практика доказала осуществимость симбиотической системы</td><td>Первопроходец симбиотической практики, почитаемая потомками как «Мать Симбиоза»</td></tr><tr><td>Máo Jué Zhě</td><td>ок. −10 000 лет</td><td>Культиватор Первой Плоскости, который в ходе долгой культивации случайно ощутил стабильный узел в сети законов и открыл механизм Якоря</td><td>Первооткрыватель механизма Якоря и зачинатель Эпохи Пробуждения Якоря</td></tr></tbody></table><h3 id="_2-2-основатели-эпохи-пробуждения-якоря" tabindex="-1">2.2 Основатели Эпохи Пробуждения Якоря <a class="header-anchor" href="#_2-2-основатели-эпохи-пробуждения-якоря" aria-label="Permalink to &quot;2.2 Основатели Эпохи Пробуждения Якоря&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Имя</th><th>Период</th><th>Ключевой вклад</th><th>Историческое положение</th></tr></thead><tbody><tr><td>Máo Dìng Gōng</td><td>−10 000 до −9200 лет</td><td>Ученик Máo Jué Zhě; систематически изучал механизм Якоря; создал первый искусственный Якорь; автор Máodiǎn Yuánlǐ (Принципы Якоря)</td><td>Основатель технологии Якоря и изобретатель искусственного Якоря</td></tr><tr><td>Gòngshēng Zǐ</td><td>−6000 до −5100 лет</td><td>Соединил технологию Якоря с симбиотической мыслью; основал теоретическую систему «Симбиоза Якоря»; автор Máodiǎn Gòngshēng Lùn (О Симбиозе Якоря)</td><td>Основатель теории Симбиоза Якоря и духовный наставник симбиотической цивилизации</td></tr><tr><td>Héngyuán Gōng</td><td>−5000 до −4300 лет</td><td>Основал первый симбиотический город-государство на основе Якоря — «Хэнъюань Чэн» — и успешно отразил атаки хищнических цивилизаций</td><td>Основатель первого симбиотического города-государства и практик симбиотической системы</td></tr><tr><td>Wànzú Shǐ</td><td>−2000 до −1200 лет</td><td>Инициировал первое «Великое Собрание Симбиоза Десяти Тысяч Рас»; объездил десятки рас, призывая к симбиотическому союзу</td><td>Поборник союза Десяти Тысяч Рас и пионер межрасового симбиоза</td></tr></tbody></table><h3 id="_2-3-основатели-государства-в-период-установления-симбиотическои-системы" tabindex="-1">2.3 Основатели государства в Период установления симбиотической системы <a class="header-anchor" href="#_2-3-основатели-государства-в-период-установления-симбиотическои-системы" aria-label="Permalink to &quot;2.3 Основатели государства в Период установления симбиотической системы&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Имя</th><th>Период</th><th>Ключевой вклад</th><th>Историческое положение</th></tr></thead><tbody><tr><td>Lìxiàn Gōng</td><td>−1000 до −900 лет</td><td>Председатель Комитета по разработке Симбиотической Конституции; руководил разработкой Симбиотической Конституции и провёл её через всенародный референдум</td><td>Главный разработчик Симбиотической Конституции и отец-основатель конституционализма симбиотической цивилизации</td></tr><tr><td>Zhífǎ Gōng</td><td>−900 до −780 лет</td><td>Первый председатель Симбиотического Исполнительного Комитета; руководил созданием административной системы и механизмов исполнения законов симбиотической цивилизации</td><td>Основатель симбиотической административной системы и первый глава администрации</td></tr><tr><td>Sīfǎ Mǔ</td><td>−900 до −800 лет</td><td>Первая председательница Верховного Суда (Симбиотического Суда); создала судебную систему и систему конституционного надзора симбиотической цивилизации</td><td>Основательница симбиотической судебной системы и первая глава судебной власти</td></tr><tr><td>Sānbǎi Shī</td><td>−500 до −300 лет</td><td>Руководил раскопкой и систематизацией Трёхсот Исходных Систем Культивации; возглавил команду, завершившую проверку всех Трёхсот Систем</td><td>Главный систематизатор Трёхсот Систем и главнокомандующий инженерии открытия культивации</td></tr><tr><td>Bèizēng Gōng</td><td>−300 до −220 лет</td><td>Руководил исследованиями технологического применения Плода Умножения; добился инженерного прорыва технологии стократного дедуктивного усиления</td><td>Главный учёный технологизации Плода Умножения и двигатель Системы Дедуктивной Итерации</td></tr></tbody></table><h3 id="_2-4-руководители-периода-открытия-и-активации" tabindex="-1">2.4 Руководители периода открытия и активации <a class="header-anchor" href="#_2-4-руководители-периода-открытия-и-активации" aria-label="Permalink to &quot;2.4 Руководители периода открытия и активации&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Имя</th><th>Период</th><th>Ключевой вклад</th><th>Историческое положение</th></tr></thead><tbody><tr><td>Kāifàng Gōng</td><td>−100 до −50 лет</td><td>Руководил полным открытием Трёхсот Исходных Систем Культивации; создал систему распределения ресурсов культивации и сеть наставников</td><td>Главнокомандующий открытия Трёхсот Систем и практик принципа «путь для каждого»</td></tr><tr><td>Jīhuó Gōng</td><td>−50 лет до первого года</td><td>Руководил реализацией Стратегии активации 20 %; возглавил команду, за 50 лет выполнившую цель активации 20 % живых существ</td><td>Главнокомандующий Стратегии активации 20 % и зачинатель новой эпохи симбиотической цивилизации</td></tr><tr><td>Shēngwéi Gōng</td><td>первый год до 80</td><td>Руководил первым проектом возвышения; продвигал реализацию Четырёхэтапного Пути Возвышения; осуществил первое поэтапное возвышение</td><td>Главный инженер первого возвышения и лидер эпохи возвышения</td></tr></tbody></table><h3 id="_2-5-исследователи-эпохи-республики-десяти-тысяч-рас-и-межплоскостнои-эпохи" tabindex="-1">2.5 Исследователи эпохи Республики Десяти Тысяч Рас и межплоскостной эпохи <a class="header-anchor" href="#_2-5-исследователи-эпохи-республики-десяти-тысяч-рас-и-межплоскостнои-эпохи" aria-label="Permalink to &quot;2.5 Исследователи эпохи Республики Десяти Тысяч Рас и межплоскостной эпохи&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Имя</th><th>Период</th><th>Ключевой вклад</th><th>Историческое положение</th></tr></thead><tbody><tr><td>Wànzú Gòngzhǔ</td><td>100 до 200</td><td>Руководил учреждением Республики Десяти Тысяч Рас; продвигал составление Реестра Десяти Тысяч Рас и политику межрасовой интеграции</td><td>Основатель Республики Десяти Тысяч Рас и первый Верховный Владыка Десяти Тысяч Рас</td></tr><tr><td>Wèimiàn Mǔ</td><td>500 до 650</td><td>Первая директриса Управления Плоскостей; руководила масштабной программой межплоскостных исследований; создала главную базу координат плоскостей</td><td>Первопроходец межплоскостных исследований и основательница системы управления плоскостями</td></tr><tr><td>Kǎogǔ Gōng</td><td>800 до 950</td><td>Руководил окончательным созреванием схемы дистанционной археологии Зеркалом Репликации; вывел межплоскостную археологию в эпоху масштаба</td><td>Венец археологических схем и основоположник межплоскостной археологии</td></tr><tr><td>Shílǜ Gōng</td><td>1000 до 1150</td><td>Руководил прорывом технологии возврата времени; продвигал установление принципа сначала наблюдение, потом ограниченное вмешательство</td><td>Лидер технологии возврата времени и создатель принципов законов времени</td></tr></tbody></table><h2 id="iii-важные-организации" tabindex="-1">III. Важные Организации <a class="header-anchor" href="#iii-важные-организации" aria-label="Permalink to &quot;III. Важные Организации&quot;">​</a></h2><h3 id="_3-1-высшие-органы-власти" tabindex="-1">3.1 Высшие органы власти <a class="header-anchor" href="#_3-1-высшие-органы-власти" aria-label="Permalink to &quot;3.1 Высшие органы власти&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Организация</th><th>Время основания</th><th>Ключевые функции</th><th>Историческая роль</th></tr></thead><tbody><tr><td>Собрание Якоря</td><td>−900 лет</td><td>Высший орган власти симбиотической цивилизации, состоящий из представителей всех рас по пропорции, осуществляющий законодательную власть и право решения важнейших вопросов</td><td>Высший орган принятия решений симбиотической цивилизации и создатель всех важнейших законов и стратегий</td></tr><tr><td>Симбиотический Исполнительный Комитет</td><td>−900 лет</td><td>Высший административный орган симбиотической цивилизации, отвечающий за исполнение конституции и законов и повседневное управление</td><td>Высший административный орган симбиотической цивилизации и исполнитель законов и политик</td></tr><tr><td>Симбиотический Суд</td><td>−900 лет</td><td>Высший судебный орган симбиотической цивилизации, независимо осуществляющий судебную власть, отвечающий за конституционный надзор и рассмотрение важнейших дел</td><td>Высший судебный орган симбиотической цивилизации и страж верховенства закона</td></tr><tr><td>Надзорный Комитет Якоря</td><td>−900 лет</td><td>Независимый надзорный орган, отвечающий за надзор за всеми органами власти с целью предотвращения злоупотребления властью</td><td>Независимый надзорный орган симбиотической цивилизации и ключевое звено баланса властей</td></tr></tbody></table><h3 id="_3-2-специализированные-органы-управления" tabindex="-1">3.2 Специализированные органы управления <a class="header-anchor" href="#_3-2-специализированные-органы-управления" aria-label="Permalink to &quot;3.2 Специализированные органы управления&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Организация</th><th>Время основания</th><th>Ключевые функции</th><th>Историческая роль</th></tr></thead><tbody><tr><td>Управление Плоскостей</td><td>500</td><td>Отвечает за ведение главной базы координат плоскостей, выдачу разрешений на переход, управление межплоскостной археологией и координацию межплоскостной дипломатии</td><td>Главный орган межплоскостного взаимодействия и управляющий исследованием плоскостей</td></tr><tr><td>Комитет Законов Времени</td><td>1000</td><td>Отвечает за утверждение операций возврата времени, исследования законов времени и надзор за предотвращением временных парадоксов</td><td>Орган утверждения и надзора операций возврата времени и страж безопасности законов времени</td></tr><tr><td>Комитет Аудита Законов Времени</td><td>1050</td><td>Отвечает за посмертный аудит операций возврата времени, подтверждая, что не вызвано неконтролируемых возмущений линии времени</td><td>Независимый орган аудита временных операций и последний рубеж безопасности возврата времени</td></tr><tr><td>Межплоскостной Этический Комитет</td><td>600</td><td>Разрабатывает и разъясняет межплоскостные этические нормы, утверждает высокорисковые межплоскостные проекты и рассматривает жалобы на нарушения этики</td><td>Орган этического надзора межплоскостного взаимодействия и страж субъектности цивилизаций</td></tr><tr><td>Управление Аудита Возврата Знаний</td><td>850</td><td>Отвечает за аудит операций возврата знаний, обеспечивая соответствие возвращаемого содержания принципу «передача только знаний»</td><td>Орган аудита возврата знаний и ключевое звено предотвращения межплоскостного загрязнения</td></tr></tbody></table><h3 id="_3-3-научно-исследовательские-и-образовательные-учреждения" tabindex="-1">3.3 Научно-исследовательские и образовательные учреждения <a class="header-anchor" href="#_3-3-научно-исследовательские-и-образовательные-учреждения" aria-label="Permalink to &quot;3.3 Научно-исследовательские и образовательные учреждения&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Организация</th><th>Время основания</th><th>Ключевые функции</th><th>Историческая роль</th></tr></thead><tbody><tr><td>НИИ Якоря</td><td>−8000 лет</td><td>Фундаментальные исследования и прикладная разработка механизма Якоря; строительство и обслуживание искусственных Якорей</td><td>Ключевой научно-исследовательский институт технологии Якоря и один из технологических истоков симбиотической цивилизации</td></tr><tr><td>Комитет по Систематизации Трёхсот Систем</td><td>−500 лет</td><td>Раскопка, систематизация, проверка и непрерывная оптимизация Трёхсот Исходных Систем Культивации</td><td>Орган систематизации и сопровождения Трёхсот Систем и техническая опора открытия культивации</td></tr><tr><td>Симбиотический Университетский Альянс</td><td>−700 лет</td><td>Объединение высшего образования и образования культивации, отвечающее за подготовку высококвалифицированных кадров и академические исследования</td><td>Альянс высших учебных заведений симбиотической цивилизации и ядро подготовки кадров и академических инноваций</td></tr><tr><td>Академия Межплоскостной Археологии</td><td>550</td><td>Готовит профессиональные кадры межплоскостной археологии; ведёт исследования археологических технологий и методологические инновации</td><td>Центр подготовки кадров и технологических разработок межплоскостной археологии</td></tr><tr><td>НИИ Законов Времени</td><td>950</td><td>Фундаментальные теоретические исследования законов времени и разработка технологии возврата времени</td><td>Ключевой институт исследований законов времени и родина технологии возврата времени</td></tr></tbody></table><h3 id="_3-4-военные-и-охранные-организации" tabindex="-1">3.4 Военные и охранные организации <a class="header-anchor" href="#_3-4-военные-и-охранные-организации" aria-label="Permalink to &quot;3.4 Военные и охранные организации&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Организация</th><th>Время основания</th><th>Ключевые функции</th><th>Историческая роль</th></tr></thead><tbody><tr><td>Симбиотические Силы Обороны</td><td>−850 лет</td><td>Регулярные оборонительные силы симбиотической цивилизации, отвечающие за оборону плоскостей и реагирование на внешние угрозы</td><td>Основная военная сила симбиотической цивилизации и защитник национальной безопасности</td></tr><tr><td>Патрульный Корпус Плоскостей</td><td>520</td><td>Отвечает за патрулирование исследованных плоскостей и охранное наблюдение, реагирует на межплоскостные происшествия</td><td>Передовая сила межплоскостной безопасности и хранитель порядка плоскостей</td></tr><tr><td>Аварийная Команда по Загрязнению Законов</td><td>600</td><td>Отвечает за экстренное реагирование на загрязнение законов и энергетическое загрязнение и ликвидацию загрязнений</td><td>Сила экстренного реагирования на загрязнение законов и защитник космической среды</td></tr><tr><td>Аварийная Группа по Временным Парадоксам</td><td>1020</td><td>Отвечает за экстренное реагирование на инциденты временных парадоксов и операции причинной починки</td><td>Сила экстренного реагирования на временные парадоксы и последняя гарантия стабильности линии времени</td></tr></tbody></table><h3 id="_3-5-гражданские-и-общественные-организации" tabindex="-1">3.5 Гражданские и общественные организации <a class="header-anchor" href="#_3-5-гражданские-и-общественные-организации" aria-label="Permalink to &quot;3.5 Гражданские и общественные организации&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Организация</th><th>Время основания</th><th>Ключевые функции</th><th>Историческая роль</th></tr></thead><tbody><tr><td>Великое Собрание Симбиоза Десяти Тысяч Рас</td><td>−2000 лет</td><td>Периодические собрания представителей десяти тысяч рас, обсуждение межрасовых симбиотических вопросов и содействие культурному обмену</td><td>Важная платформа обмена десяти тысяч рас и организация-предшественница Республики Десяти Тысяч Рас</td></tr><tr><td>Ассоциация Культиваторов</td><td>−600 лет</td><td>Самоуправляемая отраслевая организация культиваторов, отвечающая за защиту прав культиваторов и разработку отраслевых норм</td><td>Самоуправляемая организация культиваторов и двигатель стандартизации отрасли культивации</td></tr><tr><td>Ассоциация Потребителей</td><td>−650 лет</td><td>Организация защиты прав потребителей, отвечающая за защиту прав потребителей, просвещение потребителей и общественный надзор</td><td>Голос прав потребителей и общественный надзиратель рыночного порядка</td></tr><tr><td>Альянс Защиты Окружающей Среды</td><td>−550 лет</td><td>Гражданское объединение защиты окружающей среды, отвечающее за экологический надзор, экологическое просвещение и волонтёрские акции восстановления экосистем</td><td>Общественная сила защиты окружающей среды и двигатель космической экологической цивилизации</td></tr><tr><td>Общество Межплоскостной Дружбы</td><td>580</td><td>Гражданская организация, содействующая дружественному обмену между плоскостными цивилизациями, отвечающая за народную дипломатию и культурный обмен</td><td>Ключевая сила межплоскостной народной дипломатии и мост взаимопонимания между цивилизациями</td></tr></tbody></table><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Ключевые личности и организации — это живые носители истории Симбиотической Цивилизации Якоря. От древних мыслителей-предтеч до современных лидеров цивилизации, от высших органов власти до гражданских общественных организаций — каждая личность и каждая организация играют незаменимую роль в масштабном повествовании симбиотической цивилизации. Их борьба и вклад совместно ткут величественный эпос Симбиотической Цивилизации Якоря — от небытия к бытию, от малого к великому, от собственной плоскости ко всей вселенной.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>70-纪元划分总表 (Сводная таблица деления эпох)</li><li>49-治理框架与权力制衡 (Структура управления и баланс властей)</li><li>77-万族共和成立 (Основание Республики Десяти Тысяч Рас)</li></ul>',30)])])}const c=d(e,[["render",i]]);export{_ as __pageData,c as default};
